SELECT NVL(SUM(1), 0)
  FROM SJM0JM t1
 WHERE t1.CORP_GR = #{corpGr}
   AND t1.ymd     = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')
   AND t1.fund_cd = #{fundCd}
   AND (NVL(coll_pass, 0) <> 0 OR NVL(coll_up, 0) <> 0 OR NVL(coll_dw, 0) <> 0)

{CALL SR_PYUNGJAN(
    #{corpGr, mode=IN, jdbcType=VARCHAR},
    #{fundCd, mode=IN, jdbcType=VARCHAR},
    TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')
)}

SELECT TO_CHAR(CASE WHEN corp_gr = '2402' THEN NVL(junyong_ymd, hyun_ymd) ELSE hyun_ymd END, 'YYYY-MM-DD')
  FROM SZX0AA
 WHERE corp_gr = #{corpGr}
